import { Book } from "@/lib/types";

export const hebrews: Book = {
  id: "hebrews",
  name: "Hebräer",
  shortName: "Hebr",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Nachdem Gott vielfältig und auf vielerlei Weise ehemals zu den Vätern geredet hat in den* Propheten*,", heading: "Gottes Offenbarung im Sohn — Jesu Erhabenheit über die Engel", footnotes: ["o. durch die", "℘ Jer 7,25; 2Petr 3,2"] },
      { number: 2, text: "hat er am Ende dieser Tage zu uns geredet im Sohn*, den er zum Erben aller Dinge eingesetzt hat*, durch den er auch die Welten* gemacht hat*;", footnotes: ["d. h. in der Person des Sohnes, für dessen Einzigartigkeit der fehlende Artikel im Griech. bezeichnend ist\n℘ Mt 14,33", "℘ Ps 2,8; Mt 21,37.38", "o. die Zeitalter; o. die Ewigkeiten; griech. Äonen", "℘ V. 10; Joh 1,3"] },
      { number: 3, text: "er, der Ausstrahlung seiner Herrlichkeit* und Abdruck seines Wesens ist* und alle Dinge durch das Wort seiner* Macht trägt*, hat sich, nachdem er die Reinigung von den Sünden bewirkt hat*, zur Rechten der Majestät in der Höhe gesetzt*;", footnotes: ["℘ Joh 1,14", "℘ Joh 12,45; 2Kor 4,4; Kol 1,15; 2,9", "d. h. seiner eigenen", "℘ Kol 1,17", "℘ Kap. 9,12-14.26; 2Petr 1,9", "℘ V. 13; Kap. 8,1; 10,12; 12,2; Mk 16,19"] },
      { number: 4, text: "und er ist um so viel erhabener geworden als die Engel, wie er einen vorzüglicheren Namen* vor ihnen ererbt hat.", footnotes: ["℘ Phil 2,9"] },
      { number: 5, text: "Denn zu welchem der Engel hat er jemals gesagt: »Mein Sohn* bist du, ich habe dich heute gezeugt«*?, und wiederum: »Ich werde ihm Vater und er wird mir Sohn sein«*?", footnotes: ["℘ Kap. 7,28", "℘ Kap. 5,5; Ps 2,7; Lk 1,35; Apg 13,33", "℘ 1Chr 17,13; 22,10; 2Sam 7,14"] },
      { number: 6, text: "Wenn er aber den Erstgeborenen* wieder in den Erdkreis* einführt, spricht er: »Und alle Engel Gottes sollen ihn anbeten!«*", footnotes: ["℘ Ps 89,28; Kol 1,15.18", "o. die bewohnte <Erde>; so auch Kap. 2,5", "℘ Ps 97,7; Mt 4,11"] },
      { number: 7, text: "Und von den Engeln zwar spricht er: »Der seine Engel zu Winden* macht und seine Diener* zu einer Feuerflamme«*,", footnotes: ["o. zu Geistern; vgl. Anm. zu Joh 3,8", "griech. leitourgos; das Wort wurde auch für geistliche und weltliche Amtsträger verwendet", "℘ Ps 104,4"] },
      { number: 8, text: "von dem Sohn aber: »Dein Thron, Gott, ist von Ewigkeit zu Ewigkeit*, und das Zepter der Aufrichtigkeit ist Zepter deines Reiches*;", footnotes: ["w. in das Zeitalter des Zeitalters (griech. Äon)\n℘ Lk 1,33", "o. deiner Königsherrschaft\n℘ Jer 23,5"] },
      { number: 9, text: "du hast Gerechtigkeit geliebt und Gesetzlosigkeit gehasst; darum hat dich, Gott, dein Gott gesalbt* mit Freudenöl* vor deinen Gefährten.«*", footnotes: ["o. darum hat Gott, dein Gott, dich gesalbt", "w. Öl des Jubels", "℘ Ps 45,7.8"] },
      { number: 10, text: "Und: »Du, Herr, hast im Anfang die Erde gegründet, und die Himmel sind Werke deiner Hände*;", footnotes: ["℘ V. 2"] },
      { number: 11, text: "sie werden untergehen*, du aber bleibst; und sie alle werden veralten wie ein Gewand*,", footnotes: ["℘ Mt 24,35", "℘ Jes 51,6"] },
      { number: 12, text: "und wie einen Mantel wirst du sie zusammenrollen*, wie ein Gewand, und sie werden verwandelt werden. Du aber bist derselbe*, und deine Jahre werden nicht aufhören.«*", footnotes: ["℘ Offb 6,14", "d. h. der ewig Unveränderliche", "℘ Ps 102,26-28"] },
      { number: 13, text: "Zu welchem der Engel aber hat er jemals gesagt: »Setze dich zu meiner Rechten*, bis ich deine Feinde hinlege als Schemel deiner Füße«*?", footnotes: ["℘ V. 3", "℘ Kap. 10,12.13; Ps 110,1; Mt 22,44"] },
      { number: 14, text: "Sind sie nicht alle dienstbare Geister*, ausgesandt zum Dienst um derer willen, die das Heil* erben sollen*?", footnotes: ["℘ Ps 103,20.21", "o. die Rettung", "℘ Ps 91,11; Lk 16,22; Apg 5,19"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Deswegen müssen wir umso mehr auf das achten, was wir gehört haben, damit wir nicht etwa <am Ziel> vorbeigleiten*.", heading: "Warnung vor Missachtung des Heils — Jesu Erniedrigung und sein Hohepriestertum", footnotes: ["℘ Kap. 3,14"] },
      { number: 2, text: "Denn wenn das durch Engel* verkündete Wort fest war und jede Übertretung und jeder Ungehorsam gerechte Vergeltung empfing*,", footnotes: ["℘ Apg 7,53; Gal 3,19", "℘ Kap. 10,28; 4Mo 15,30"] },
      { number: 3, text: "wie werden wir entfliehen, wenn wir eine so große Rettung* missachten*? Sie ist <ja>, nachdem sie ihren Anfang <damit> genommen hatte, dass sie durch den Herrn verkündet wurde*, uns gegenüber von denen bestätigt worden, die es gehört haben*,", footnotes: ["o. ein so großes Heil", "℘ Kap. 10,29; 12,25", "℘ Mk 1,14", "℘ Lk 1,2"] },
      { number: 4, text: "wobei Gott zugleich Zeugnis gab durch Zeichen und Wunder und mancherlei Machttaten* und Austeilungen des Heiligen Geistes* nach seinem Willen*.", footnotes: ["℘ Kap. 6,5; Mk 16,20; Apg 4,30; 8,17; Röm 15,19", "℘ Gal 3,5", "℘ 1Kor 12,4.11"] },
      { number: 5, text: "Denn nicht Engeln hat er den zukünftigen Erdkreis unterworfen, von dem wir reden;" },
      { number: 6, text: "es hat aber irgendwo jemand bezeugt und gesagt: »Was ist der Mensch, dass du seiner gedenkst, oder des Menschen Sohn, dass du auf ihn achtest*?", footnotes: ["℘ Hi 7,17; Ps 144,3"] },
      { number: 7, text: "Du hast ihn ein wenig* unter die Engel erniedrigt*; mit Herrlichkeit und Ehre hast du ihn gekrönt*;", footnotes: ["o. kurze Zeit", "w. geringer gemacht als die Engel; so auch V. 9", "w. bekränzt; so auch V. 9"] },
      { number: 8, text: "du hast alles unter seine Füße gelegt*.«* Denn indem er ihm alles unterwarf, ließ er nichts übrig, das ihm nicht unterworfen wäre*; jetzt aber sehen wir ihm noch nicht alles unterworfen.", footnotes: ["w. unterworfen", "℘ Ps 8,5-7; Mt 28,18", "℘ 1Kor 15,27"] },
      { number: 9, text: "*Wir sehen aber Jesus, der ein wenig* unter die Engel erniedrigt war, wegen des Todesleidens* mit Herrlichkeit und Ehre gekrönt*, damit er durch Gottes Gnade für jeden* den Tod schmeckte*.", footnotes: ["o. Wir sehen aber Jesus, der wegen des Todesleidens ein wenig unter die Engel erniedrigt war,", "o. kurze Zeit", "o. kurze Zeit", "℘ Phil 2,8.9", "o. für alles", "℘ 2Kor 5,14"] },
      { number: 10, text: "Denn es geziemte ihm, um dessentwillen alle Dinge und durch den alle Dinge sind*, indem er viele Söhne zur Herrlichkeit führte*, den Urheber ihrer Rettung* durch Leiden vollkommen zu machen*.", footnotes: ["℘ Kap. 3,4; Röm 11,36", "℘ Joh 12,24; Röm 8,30", "o. ihres Heils", "℘ Kap. 5,8.9; 7,28"] },
      { number: 11, text: "Denn sowohl der, welcher heiligt, als auch die, welche geheiligt werden*, sind alle von einem; aus diesem Grund schämt er sich nicht, sie Brüder zu nennen*,", footnotes: ["℘ Kap. 10,10.14; Joh 17,19", "℘ Mt 25,40; Joh 20,17; Röm 8,29"] },
      { number: 12, text: "indem er spricht: »Kundtun will ich deinen Namen meinen Brüdern; inmitten der Gemeinde* will ich dir lobsingen.«*", footnotes: ["o. Versammlung", "℘ Ps 22,23"] },
      { number: 13, text: "Und wiederum: »Ich will mein Vertrauen auf ihn setzen.«* Und wiederum: »Siehe, ich und die Kinder, die Gott mir gegeben hat.«*", footnotes: ["℘ 2Sam 22,3; Ps 16,1; Jes 8,17", "℘ Jes 8,18; Joh 17,6"] },
      { number: 14, text: "Weil nun die Kinder Blutes und Fleisches teilhaftig sind, hat auch er in gleicher Weise* daran Anteil gehabt*, um durch den Tod den zunichte zu machen, der die Macht des Todes hat, das ist den Teufel*,", footnotes: ["o. in ähnlicher Weise, o. fast ebenso; der griech. Ausdruck lässt beide Möglichkeiten (gleich — fast gleich) zu", "℘ Kap. 10,5; Joh 1,14; Röm 8,3", "℘ 2Tim 1,10"] },
      { number: 15, text: "und um alle die zu befreien, die durch Todesfurcht das ganze Leben hindurch der Knechtschaft* unterworfen waren.", footnotes: ["o. Sklaverei"] },
      { number: 16, text: "Denn er nimmt sich doch wohl nicht der Engel an, sondern der Nachkommenschaft* Abrahams* nimmt er sich an.", footnotes: ["w. des Samens", "℘ Gal 3,29"] },
      { number: 17, text: "Daher musste er in allem den Brüdern gleich werden*, damit er barmherzig und ein treuer Hoherpriester vor Gott* werde*, um die Sünden des Volkes zu sühnen*;", footnotes: ["℘ Phil 2,7", "w. im Blick auf die <Beziehungen> zu Gott", "℘ Kap. 4,15", "℘ Mt 1,21"] },
      { number: 18, text: "denn worin er selbst gelitten hat, als er versucht worden ist, kann er denen helfen, die versucht werden*.", footnotes: ["℘ Kap. 4,16"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Daher, heilige Brüder, Teilhaber der himmlischen Berufung*, betrachtet den Apostel* und Hohenpriester unseres Bekenntnisses, Jesus*,", heading: "Jesu Erhabenheit über Mose — Warnung vor Unglauben und Abfall", footnotes: ["℘ Eph 4,1; Phil 3,14; 2Tim 1,9; Offb 17,14", "℘ Joh 17,18", "℘ Kap. 4,14"] },
      { number: 2, text: "der treu ist dem, der ihn <dazu> gemacht hat*, wie auch Mose in seinem ganzen Hause*!", footnotes: ["℘ Joh 17,4", "℘ 4Mo 12,7"] },
      { number: 3, text: "Denn er ist größerer Herrlichkeit gewürdigt worden als Mose, insofern größere Ehre als das Haus* der hat, der es erbaut hat.", footnotes: ["℘ Sach 6,12.13"] },
      { number: 4, text: "Denn jedes Haus wird von jemand erbaut; der aber alles erbaut hat, ist Gott*.", footnotes: ["℘ Kap. 2,10"] },
      { number: 5, text: "Und Mose war zwar in seinem ganzen Hause als Diener treu* — zum Zeugnis von dem, was verkündigt werden sollte* —,", footnotes: ["℘ 4Mo 12,7", "℘ 5Mo 4,5"] },
      { number: 6, text: "Christus aber als Sohn über sein Haus*. Sein Haus sind wir*, wenn wir die Freimütigkeit und den Ruhm der Hoffnung* *bis zum Ende standhaft* festhalten*.", footnotes: ["℘ Kap. 10,21", "℘ Eph 2,21.22", "o. das Rühmen aufgrund der Hoffnung", "in einigen alten Handschr. nicht enthalten", "in einigen alten Handschr. nicht enthalten", "℘ V. 14; Kap. 6,11; 10,23; Mt 24,13"] },
      { number: 7, text: "Deshalb, wie der Heilige Geist spricht: »Heute*, wenn ihr seine Stimme hört,", footnotes: ["℘ 2Kor 6,2"] },
      { number: 8, text: "verhärtet eure Herzen nicht*, wie in der Erbitterung* an dem Tage der Versuchung in der Wüste*,", footnotes: ["℘ Kap. 4,7; 1Sam 6,6; Sach 7,12", "℘ V. 15", "℘ 2Mo 17,2; 4Mo 20,2"] },
      { number: 9, text: "wo eure Väter <mich> versuchten, indem sie <mich> auf die Probe stellten*, und sie sahen meine Werke", footnotes: ["℘ 5Mo 9,22.23"] },
      { number: 10, text: "vierzig Jahre*. Deshalb zürnte ich diesem Geschlecht* und sprach: Allezeit gehen sie irre mit dem Herzen. Sie aber haben meine Wege nicht erkannt.", footnotes: ["℘ 5Mo 8,2-4", "℘ Ps 78,21"] },
      { number: 11, text: "So schwor ich in meinem Zorn: Sie sollen nimmermehr in meine Ruhe eingehen*!«*", footnotes: ["w. Wenn sie in meine Ruhe eingehen werden (Hebraismus, der die Verneinung betont)", "℘ Kap. 4,3.5; 4Mo 14,21-23; 5Mo 1,34.35; Ps 95,7-11"] },
      { number: 12, text: "Seht zu, Brüder, dass nicht etwa in jemandem von euch ein böses Herz des Unglaubens sei*, im Abfall vom lebendigen Gott*,", footnotes: ["℘ 2Kor 13,5", "℘ Jer 11,8"] },
      { number: 13, text: "sondern ermuntert* einander* jeden Tag, solange es »heute« heißt, damit niemand von euch verhärtet werde durch Betrug der Sünde!", footnotes: ["o. ermahnt", "℘ Kap. 10,25; 1Thes 5,11"] },
      { number: 14, text: "Denn wir sind Teilhaber des Christus geworden, wenn wir die anfängliche Grundlage* bis zum Ende standhaft festhalten*.", footnotes: ["o. die anfängliche Zuversicht; o. die anfängliche Standhaftigkeit; w. den Anfang der Grundlage", "℘ V. 6; Offb 2,26"] },
      { number: 15, text: "Wenn gesagt wird: »Heute, wenn ihr seine Stimme hört, verhärtet eure Herzen nicht wie in der Erbitterung«*;", footnotes: ["℘ V. 7.8"] },
      { number: 16, text: "welche haben denn gehört und sich aufgelehnt*? <Waren es> denn nicht alle, die durch Mose von Ägypten ausgezogen waren*?", footnotes: ["w. erbittert", "℘ 4Mo 14,29"] },
      { number: 17, text: "Welchen aber zürnte er vierzig Jahre? Nicht denen, welche gesündigt hatten, deren Leiber* in der Wüste fielen*?", footnotes: ["w. Glieder; Ausdruck für herumliegende Leichname", "℘ 4Mo 14,32.33; 1Kor 10,5"] },
      { number: 18, text: "Welchen aber schwor er, dass sie nicht in seine Ruhe eingehen sollten, wenn nicht denen, die ungehorsam gewesen waren*?", footnotes: ["o. die den Glaubensgehorsam verweigert hatten\n℘ Kap. 4,11; 5Mo 1,26; Ps 106,21-26"] },
      { number: 19, text: "Und wir sehen, dass sie wegen des Unglaubens nicht hineingehen konnten*.", footnotes: ["℘ Kap. 4,2.6; Mt 17,20; Jud 5"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Fürchten wir uns nun, dass nicht etwa — da die Verheißung, in seine Ruhe einzugehen, noch aussteht — jemand von euch als zurückgeblieben erscheint*.", heading: "Die Sabbatruhe des Gottesvolkes — Vom Wesen und Wirken des Wortes Gottes", footnotes: ["o. meint, <sie> versäumt zu haben"] },
      { number: 2, text: "Denn auch uns ist eine gute Botschaft* verkündigt worden, wie auch jenen; aber das gehörte Wort* nützte jenen nicht, weil es bei denen, die es hörten, sich nicht mit dem Glauben verband*.", footnotes: ["o. das Evangelium", "o. das Wort der Kunde; w. das Wort des Hörens", "℘ 5Mo 1,32; Röm 10,16"] },
      { number: 3, text: "Wir gehen nämlich in die Ruhe ein als die, die geglaubt haben, wie er gesagt hat: »So schwor ich in meinem Zorn: Sie sollen nimmermehr in meine Ruhe eingehen*!«*, obwohl die Werke von Grundlegung der Welt an geschaffen* waren.", footnotes: ["w. Wenn sie in meine Ruhe eingehen werden (Hebraismus, der die Verneinung betont)", "℘ Kap. 3,11; Ps 95,11", "w. geworden"] },
      { number: 4, text: "Denn er hat irgendwo von dem siebten <Tag> so gesprochen: »Und Gott ruhte am siebten Tag von allen seinen Werken.«*", footnotes: ["℘ 1Mo 2,2"] },
      { number: 5, text: "Und an dieser <Stelle> wiederum: »Sie sollen nimmermehr in meine Ruhe eingehen*!«*", footnotes: ["w. Wenn sie in meine Ruhe eingehen werden (Hebraismus, der die Verneinung betont)", "℘ Kap. 3,11"] },
      { number: 6, text: "Weil es nun dabei bleibt, dass einige in sie eingehen und die, denen zuerst die gute Botschaft* verkündigt worden ist, des Ungehorsams wegen nicht hineingegangen sind*,", footnotes: ["o. das Evangelium", "℘ Kap. 3,19"] },
      { number: 7, text: "bestimmt er wieder einen Tag, ein »Heute«, und sagt durch David nach so langer Zeit, wie vorhin gesagt worden ist: »Heute, wenn ihr seine Stimme hört, verhärtet eure Herzen nicht!«*", footnotes: ["℘ Kap. 3,7.8"] },
      { number: 8, text: "Denn wenn Josua* sie in die Ruhe gebracht hätte*, würde er danach nicht von einem anderen Tag geredet haben.", footnotes: ["griech. Jesus", "℘ Jos 21,44; 22,4"] },
      { number: 9, text: "Also bleibt noch eine Sabbatruhe dem Volk Gottes übrig*.", footnotes: ["℘ Jes 14,3; Jer 31,2"] },
      { number: 10, text: "Denn wer in seine Ruhe eingegangen ist, der ist auch zur Ruhe gelangt von seinen Werken* wie Gott von seinen eigenen*.", footnotes: ["℘ Offb 14,13", "℘ 2Mo 20,11"] },
      { number: 11, text: "Lasst uns nun eifrig sein, in jene Ruhe einzugehen*, damit nicht jemand nach demselben Beispiel des Ungehorsams falle*!", footnotes: ["℘ Jos 18,3", "℘ Kap. 3,18"] },
      { number: 12, text: "Denn das Wort Gottes ist lebendig* und wirksam* und schärfer als jedes zweischneidige Schwert* und durchdringend bis zur Scheidung von Seele und Geist*, sowohl der Gelenke als auch des Markes, und ein Richter* der Gedanken und Gesinnungen des Herzens*;", footnotes: ["℘ Apg 7,38; 1Petr 1,23", "℘ Jes 55,11; Jer 23,29", "℘ Jes 49,2; Eph 6,17", "℘ 1Thes 5,23", "w. ein Urteilsfähiger (griech. kritikos)", "℘ 1Kor 14,25"] },
      { number: 13, text: "und kein Geschöpf ist vor ihm unsichtbar*, sondern alles bloß und aufgedeckt vor den Augen dessen, mit dem wir es zu tun haben*.", footnotes: ["℘ Jer 23,24; Joh 2,25", "℘ Ps 33,13-15; 90,8; 1Jo 3,20"] },
      { number: 14, text: "Da wir nun einen großen Hohenpriester haben*, der durch die Himmel gegangen ist*, Jesus*, den Sohn Gottes*, so lasst uns das Bekenntnis festhalten*!", heading: "Jesu Erhabenheit über die Hohenpriester des Alten Testaments — Sein Priestertum nach der Ordnung Melchisedeks", footnotes: ["℘ Kap. 8,1", "℘ Kap. 7,26", "℘ Kap. 3,1", "℘ Kap. 5,5", "℘ Kap. 10,23"] },
      { number: 15, text: "Denn wir haben nicht einen Hohenpriester, der nicht Mitleid haben könnte mit unseren Schwachheiten, sondern der in allem in gleicher Weise <wie wir> versucht worden ist*, <doch> ohne Sünde*.", footnotes: ["℘ 1Petr 1,6", "℘ Kap. 7,26; Joh 8,46"] },
      { number: 16, text: "Lasst uns nun mit Freimütigkeit hinzutreten* zum Thron der Gnade*, damit wir Barmherzigkeit empfangen und Gnade finden zur rechtzeitigen Hilfe*!", footnotes: ["℘ Kap. 10,19-22", "℘ Röm 3,25", "℘ Kap. 2,17.18"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Denn jeder aus Menschen genommene Hohepriester wird für Menschen eingesetzt im Blick auf das <Verhältnis> zu Gott*, damit er sowohl Gaben als auch Schlachtopfer für Sünden darbringe*,", footnotes: ["℘ 1Chr 23,13", "℘ Kap. 8,3"] },
      { number: 2, text: "wobei er Nachsicht zu haben vermag mit den Unwissenden und Irrenden*, da auch er selbst mit Schwachheit behaftet ist*;", footnotes: ["℘ 4Mo 15,22-29", "℘ Kap. 7,28"] },
      { number: 3, text: "und um ihretwillen muss er, wie für das Volk, so auch für sich selbst, der Sünden wegen opfern*.", footnotes: ["℘ Kap. 7,27; 3Mo 9,7; 16,6"] },
      { number: 4, text: "Und niemand nimmt sich selbst die Ehre, sondern er wird von Gott berufen wie auch Aaron*.", footnotes: ["℘ 2Mo 28,1"] },
      { number: 5, text: "So hat auch der Christus sich nicht selbst verherrlicht*, um Hoherpriester zu werden, sondern der, welcher zu ihm gesagt hat: »Mein Sohn bist du, ich habe dich heute gezeugt.«*", footnotes: ["℘ Joh 17,1.5", "℘ Kap. 1,5; Ps 2,7"] },
      { number: 6, text: "Wie er auch an einer anderen <Stelle> sagt: »Du bist Priester in Ewigkeit* nach der Ordnung Melchisedeks.«*", footnotes: ["griech. Äon", "℘ V. 10; Kap. 6,20; 7,17.21; Ps 110,4"] },
      { number: 7, text: "Der hat in den Tagen seines Fleisches sowohl Bitten als auch Flehen mit starkem Geschrei und Tränen dem dargebracht*, der ihn aus dem Tod retten kann, und ist um seiner Gottesfurcht willen erhört worden*,", footnotes: ["℘ Ps 69,4; Mt 27,46", "℘ Ps 22,25; Joh 11,42"] },
      { number: 8, text: "und lernte, obwohl er Sohn war, an dem, was er litt, den Gehorsam*;", footnotes: ["℘ Jes 50,5; Phil 2,8"] },
      { number: 9, text: "und vollendet* ist er allen, die ihm gehorchen, der Urheber ewigen Heils* geworden*,", footnotes: ["o. vollkommen gemacht\n℘ Kap. 2,10", "o. ewiger Rettung", "℘ Jes 45,17"] },
      { number: 10, text: "von Gott begrüßt* als Hoherpriester nach der Ordnung Melchisedeks*.", footnotes: ["o. bezeichnet; o. angeredet", "℘ Kap. 7,3"] },
      { number: 11, text: "Darüber haben wir viel zu sagen, und es lässt sich schwer darlegen, weil ihr im Hören träge geworden seid.", heading: "Geistliche Unreife der Leser — Mahnung zum Ausharren — Trost im Blick auf das Ziel" },
      { number: 12, text: "Denn während ihr der Zeit nach Lehrer sein solltet, habt ihr wieder nötig, dass man euch lehre, was die Anfangsgründe* der Aussprüche Gottes sind; und ihr seid solche geworden, die Milch nötig haben und nicht feste Speise*.", footnotes: ["w. die Elemente des Anfangs\n℘ Kap. 6,1", "℘ 1Kor 3,2"] },
      { number: 13, text: "Denn jeder, der noch Milch genießt, ist richtiger Rede* unkundig, denn er ist ein Unmündiger*;", footnotes: ["o. des Wortes der Gerechtigkeit", "℘ 1Kor 3,1; 14,20; Eph 4,14"] },
      { number: 14, text: "die feste Speise aber ist für Erwachsene*, die infolge der Gewöhnung geübte Sinne haben zur Unterscheidung des Guten wie auch des Bösen*.", footnotes: ["w. Vollkommene; im Griech. ein Ausdruck für »Erwachsene«", "℘ 1Kö 3,9"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Deshalb wollen wir das Wort vom Anfang des Christus lassen* und uns der vollen Reife* zuwenden* und nicht wieder einen Grund legen mit der Buße von toten Werken* und dem Glauben an Gott,", footnotes: ["℘ Kap. 5,12", "o. Vollkommenheit; s. vorige Anm.", "℘ Mt 5,48", "℘ Kap. 9,14"] },
      { number: 2, text: "der Lehre von Waschungen und der Handauflegung*, der Totenauferstehung* und dem ewigen Gericht*.", footnotes: ["℘ 3Mo 1,4", "℘ 1Kor 15,12", "℘ Kap. 9,27"] },
      { number: 3, text: "Und dies werden wir tun, wenn Gott es erlaubt*.", footnotes: ["℘ Apg 18,21"] },
      { number: 4, text: "Denn es ist unmöglich, diejenigen, die einmal erleuchtet worden sind* und die himmlische Gabe geschmeckt haben und des Heiligen Geistes teilhaftig geworden sind", footnotes: ["℘ Kap. 10,26"] },
      { number: 5, text: "und das gute Wort Gottes* und die Kräfte des zukünftigen Zeitalters* geschmeckt haben*", footnotes: ["℘ Mt 13,20", "griech. Äon", "℘ Kap. 2,4"] },
      { number: 6, text: "und <doch> abgefallen sind, wieder zur Buße zu erneuern, da* sie für sich den Sohn Gottes wieder kreuzigen und dem Spott aussetzen.", footnotes: ["o. indem"] },
      { number: 7, text: "Denn ein Land, das den häufig darauf kommenden Regen trinkt und nützliches Kraut hervorbringt für diejenigen, um derentwillen es auch bebaut wird, empfängt Segen von Gott*;", footnotes: ["℘ Ps 65,11"] },
      { number: 8, text: "wenn es aber Dornen und Disteln hervorbringt, so ist es unbrauchbar und dem Fluch nahe, der am Ende zur Verbrennung führt*.", footnotes: ["℘ Jes 5,6; 1Mo 1,11.12; 3,17.18"] },
      { number: 9, text: "Wir aber sind, wenn wir auch so reden, im Hinblick auf euch, Geliebte, vom Besseren und zum Heil* Dienlichen überzeugt.", footnotes: ["o. zur Rettung"] },
      { number: 10, text: "Denn Gott ist nicht ungerecht*, euer Werk zu vergessen* und die Liebe, die ihr zu seinem Namen bewiesen habt, indem ihr den Heiligen gedient habt und dient*.", footnotes: ["℘ 1Mo 18,25; 5Mo 32,4", "℘ Offb 2,2", "℘ Kap. 10,34; Mt 10,42; 1Kor 16,15; 1Thes 1,3"] },
      { number: 11, text: "Wir wünschen aber sehr*, dass jeder von euch denselben Eifer um die volle Gewissheit* der Hoffnung bis ans Ende beweise*,", footnotes: ["w. Wir begehren aber", "o. die Fülle", "℘ Kap. 3,6"] },
      { number: 12, text: "damit ihr nicht träge werdet*, sondern Nachahmer derer, die durch Glauben und Ausharren die Verheißungen erben*.", footnotes: ["℘ Kap. 13,16; Gal 6,9.10", "℘ Kap. 10,36; 11,33; Offb 13,10"] },
      { number: 13, text: "Denn als Gott dem Abraham die Verheißung gab, schwor er bei sich selbst — weil er bei keinem Größeren schwören konnte —" },
      { number: 14, text: "und sprach: »Wahrlich, reichlich* werde ich dich segnen, und sehr* werde ich dich mehren.«*", footnotes: ["w. segnend", "w. mehrend", "℘ 1Mo 22,16.17"] },
      { number: 15, text: "Und so erlangte er, indem er ausharrte, die Verheißung*.", footnotes: ["℘ 1Mo 21,2; Jak 5,11"] },
      { number: 16, text: "Denn Menschen schwören bei einem Größeren, und der Eid ist ihnen zur Bestätigung ein Ende alles Widerspruchs*.", footnotes: ["℘ 2Mo 22,10"] },
      { number: 17, text: "Deshalb hat sich Gott, da er den Erben der Verheißung* die Unwandelbarkeit seines Ratschlusses noch viel deutlicher beweisen wollte, mit einem Eid verbürgt*,", footnotes: ["℘ Kap. 11,9; Gal 3,29", "℘ Lk 1,73"] },
      { number: 18, text: "damit wir durch zwei unveränderliche Dinge, bei denen Gott <doch> unmöglich lügen kann*, einen starken Trost hätten, die wir unsere Zuflucht dazu genommen haben, die vorhandene Hoffnung zu ergreifen*.", footnotes: ["℘ Tit 1,2", "℘ Kap. 10,23"] },
      { number: 19, text: "Diese haben wir als einen sicheren und festen Anker der Seele, der in das Innere des Vorhangs* hineinreicht*,", footnotes: ["d. h. in das Allerheiligste", "℘ 3Mo 16,12.15"] },
      { number: 20, text: "wohin Jesus als Vorläufer für uns hineingegangen ist, der nach der Ordnung Melchisedeks Hoherpriester in Ewigkeit* geworden ist*.", footnotes: ["griech. Äon", "℘ Kap. 5,6"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Denn dieser Melchisedek, König von Salem, Priester Gottes, des Höchsten, — der Abraham entgegenging und ihn segnete, als er von der Niederwerfung der Könige zurückkehrte,", heading: "Das Hohepriestertum Jesu ist erhaben über das levitische Priestertum" },
      { number: 2, text: "dem auch Abraham den Zehnten von allem zuteilte* — <heißt> übersetzt zunächst König der Gerechtigkeit*, dann aber auch König von Salem, das ist König des Friedens*.", footnotes: ["℘ 1Mo 14,18-20", "℘ Jer 23,5", "℘ Jes 9,5.6"] },
      { number: 3, text: "Ohne Vater, ohne Mutter, ohne Geschlechtsregister, hat er weder Anfang der Tage noch Ende des Lebens, er gleicht* dem Sohn Gottes und bleibt Priester für immer.", footnotes: ["d. h. in den angegebenen Erscheinungsmerkmalen, wobei der Sohn Gottes das Urbild, Melchisedek das Abbild ist"] },
      { number: 4, text: "Schaut aber, wie groß dieser ist, dem Abraham, der Patriarch, den Zehnten von der Beute gab*!", footnotes: ["℘ 1Mo 14,18-20"] },
      { number: 5, text: "Und zwar haben die von den Söhnen Levi, die das Priestertum empfangen, ein Gebot, den Zehnten von dem Volk nach dem Gesetz zu nehmen, das ist von ihren Brüdern*, obwohl <auch> die aus der Lende Abrahams hervorgegangen sind.", footnotes: ["℘ 4Mo 18,21; 2Chr 31,4-6"] },
      { number: 6, text: "Er aber, der sein Geschlecht nicht von ihnen ableitete, hat den Zehnten von Abraham genommen* und den gesegnet, der die Verheißungen hatte*.", footnotes: ["℘ 1Mo 14,18-20", "℘ 1Mo 12,2.3; Gal 3,16"] },
      { number: 7, text: "Ohne jeden Widerspruch aber wird das Geringere von dem Besseren* gesegnet*.", footnotes: ["o. Höheren", "℘ 3Mo 9,22.23"] },
      { number: 8, text: "Und hier zwar empfangen sterbliche Menschen die Zehnten, dort aber einer, von dem bezeugt wird, dass er lebt;" },
      { number: 9, text: "und sozusagen ist durch Abraham auch von Levi, der die Zehnten empfängt, der Zehnte erhoben worden," },
      { number: 10, text: "denn er war noch in der Lende des Vaters, als Melchisedek ihm entgegenging." },
      { number: 11, text: "Wenn nun die Vollendung durch das levitische Priestertum <erreicht worden> wäre — denn in Verbindung mit ihm hat das Volk das Gesetz empfangen* —, welche Notwendigkeit <bestand dann> noch, einen anderen Priester nach der Ordnung Melchisedeks aufzustellen und nicht nach der Ordnung Aarons zu nennen?", footnotes: ["℘ 5Mo 17,11"] },
      { number: 12, text: "Denn wenn das Priestertum geändert wird, so findet notwendig auch eine Änderung des Gesetzes statt." },
      { number: 13, text: "Denn der, von dem dies gesagt wird, gehört zu einem anderen Stamm, aus dem niemand die Wartung des Altars hatte." },
      { number: 14, text: "Denn es ist offenbar, dass unser Herr aus Juda entsprossen* ist*, von welchem Stamm Mose nichts in Bezug auf Priester geredet hat.", footnotes: ["o. aufgegangen", "℘ Mt 1,3; Offb 5,5"] },
      { number: 15, text: "Und es ist noch weit augenscheinlicher, wenn gleich dem Melchisedek* ein anderer Priester aufsteht,", footnotes: ["w. in Gleichheit Melchisedeks"] },
      { number: 16, text: "der es nicht nach dem Gesetz eines fleischlichen Gebots* geworden ist*, sondern nach der Kraft eines unauflöslichen Lebens*.", footnotes: ["℘ Kap. 9,10", "℘ 2Mo 28,1", "℘ Röm 6,9"] },
      { number: 17, text: "Denn ihm wird bezeugt: »Du bist Priester in Ewigkeit* nach der Ordnung Melchisedeks.«*", footnotes: ["griech. Äon", "℘ Kap. 5,6; Ps 110,4"] },
      { number: 18, text: "Denn aufgehoben wird zwar das vorhergehende Gebot seiner Schwachheit* und Nutzlosigkeit wegen*", footnotes: ["℘ Röm 8,3", "℘ Kap. 8,7; 2Kor 3,11"] },
      { number: 19, text: "— denn das Gesetz hat nichts zur Vollendung gebracht* —, eingeführt aber eine bessere Hoffnung*, durch die wir uns Gott nahen.", footnotes: ["℘ Kap. 9,9; 10,1; Gal 2,16", "℘ Kap. 10,9"] },
      { number: 20, text: "Und wie <dies> nicht ohne Eid <geschah> — denn jene sind ohne Eid Priester geworden," },
      { number: 21, text: "dieser aber mit Eid durch den, der zu ihm* sprach: »Der Herr hat geschworen, und es wird ihn nicht gereuen: Du bist Priester in Ewigkeit*!«* —,", footnotes: ["o. im Blick auf ihn", "griech. Äon", "℘ Kap. 5,6"] },
      { number: 22, text: "so ist Jesus auch eines besseren Bundes Bürge geworden*.", footnotes: ["℘ Kap. 8,6"] },
      { number: 23, text: "Und jene sind in größerer Anzahl Priester geworden, weil sie durch den Tod verhindert waren zu bleiben;" },
      { number: 24, text: "dieser aber, weil er in Ewigkeit* bleibt*, hat ein unveränderliches* Priestertum.", footnotes: ["griech. Äon", "℘ Kap. 13,8; Offb 1,18", "vielleicht auch: unübertragbares"] },
      { number: 25, text: "Daher kann er die auch völlig retten, die sich durch ihn Gott nahen*, weil er immer lebt, um sich für sie zu verwenden*.", footnotes: ["℘ Kap. 10,19", "o. für sie einzutreten\n℘ Kap. 9,24; Joh 17,9.15; 1Jo 2,1"] },
      { number: 26, text: "Denn ein solcher Hoherpriester geziemte sich auch für uns: heilig, sündlos, unbefleckt, abgesondert von den Sündern* und höher als die Himmel geworden*,", footnotes: ["℘ Kap. 4,15; 1Petr 2,22", "℘ Kap. 4,14; Eph 4,10"] },
      { number: 27, text: "der nicht Tag für Tag* nötig hat, wie die Hohenpriester, zuerst für die eigenen Sünden Schlachtopfer darzubringen*, dann für die des Volkes*; denn dies hat er ein für alle Mal* getan, als er sich selbst dargebracht hat*.", footnotes: ["℘ Kap. 10,11", "℘ Kap. 5,3", "℘ 3Mo 9,15; 16,15", "℘ Kap. 9,12; Röm 6,10", "℘ Kap. 9,26; 10,10"] },
      { number: 28, text: "Denn das Gesetz setzt Menschen als Hohepriester ein, die mit Schwachheit behaftet sind*, das Wort des Eides aber, das später als das Gesetz <gegeben wurde>, einen Sohn*, der in Ewigkeit* vollendet* ist*.", footnotes: ["℘ Kap. 5,2", "℘ Kap. 1,5", "griech. Äon", "o. vollkommen gemacht", "℘ Kap. 2,10"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Die Hauptsache aber bei dem, was wir sagen, ist: Wir haben einen solchen Hohenpriester*, der sich gesetzt hat zur Rechten des Thrones der Majestät* in den Himmeln*,", heading: "Jesus der Mittler eines neuen und besseren Bundes", footnotes: ["℘ Kap. 4,14", "℘ Kap. 1,3; Offb 3,21", "℘ Kap. 9,24"] },
      { number: 2, text: "als Diener* des Heiligtums und des wahrhaftigen Zeltes, das der Herr errichtet hat, nicht ein Mensch*.", footnotes: ["griech. leitourgos; das Wort wurde auch für geistliche und weltliche Amtsträger verwendet", "℘ Kap. 9,11.24"] },
      { number: 3, text: "Denn jeder Hohepriester wird eingesetzt, um sowohl Gaben als auch Schlachtopfer darzubringen*; daher ist es notwendig, dass auch dieser etwas hat, das er darbringt*.", footnotes: ["℘ Kap. 5,1", "℘ Eph 5,2"] },
      { number: 4, text: "Wenn er nun auf Erden wäre, so wäre er nicht einmal Priester, weil die da sind, die nach dem Gesetz die Gaben darbringen" },
      { number: 5, text: "— die dem Abbild und Schatten der himmlischen Dinge* dienen, wie Mose eine göttliche Weisung empfing, als er im Begriff war, das Zelt aufzurichten; denn »Sieh <zu>«, spricht er, »dass du alles nach dem Muster machst, das dir auf dem Berge gezeigt worden ist!«*. —", footnotes: ["℘ Kap. 9,23; 10,1; Kol 2,17", "℘ 2Mo 25,40; Apg 7,44"] },
      { number: 6, text: "Jetzt aber hat er einen vortrefflicheren Dienst erlangt*, wie er auch Mittler* eines besseren Bundes ist*, der aufgrund besserer Verheißungen gestiftet worden ist*.", footnotes: ["℘ 2Kor 3,9", "℘ 1Tim 2,5", "℘ Kap. 7,22; 9,15; 12,24", "℘ 2Petr 1,4"] },
      { number: 7, text: "Denn wenn jener erste <Bund> tadellos wäre, so wäre kein Raum für einen zweiten gesucht worden*.", footnotes: ["℘ Kap. 7,18.19"] },
      { number: 8, text: "Denn tadelnd spricht er zu ihnen*: »Siehe, es kommen Tage, spricht der Herr, da werde ich mit dem Haus Israel und mit dem Haus Juda einen neuen Bund schließen,", footnotes: ["℘ Kap. 10,16.17"] },
      { number: 9, text: "nicht nach der Art des Bundes, den ich mit ihren Vätern machte an dem Tag, da ich ihre Hand ergriff, um sie aus dem Land Ägypten herauszuführen*; denn sie blieben nicht in meinem Bund, und ich kümmerte mich nicht um sie, spricht der Herr*.", footnotes: ["℘ 5Mo 4,37; 5,6", "℘ 2Kö 17,15-20; Ps 78,10.59"] },
      { number: 10, text: "Denn dies ist der Bund*, den ich dem Haus Israel errichten werde* nach jenen Tagen, spricht der Herr: Meine Gesetze gebe ich in ihren Sinn* und werde sie auch auf ihre Herzen schreiben; und ich werde ihnen Gott und sie werden mir Volk sein*.", footnotes: ["℘ Jes 56,3; Hes 37,26", "o. mit dem Haus Israel schließen werde; o. den ich für das Haus Israel anordnen werde", "o. ihre Gesinnung; o. ihr Denken", "℘ Hes 36,28; Sach 8,8; 2Kor 6,16"] },
      { number: 11, text: "Und nicht werden sie ein jeder seinen Mitbürger und ein jeder seinen Bruder lehren und sagen: Erkenne den Herrn! Denn alle werden mich kennen, vom Kleinen* bis zum Großen unter ihnen*.", footnotes: ["o. Geringen", "℘ Jes 54,13"] },
      { number: 12, text: "Denn ich werde gegenüber ihren Ungerechtigkeiten gnädig sein, und ihrer Sünden werde ich nie mehr gedenken.«*", footnotes: ["℘ Jer 31,31-34; 33,8; Jes 43,25"] },
      { number: 13, text: "Indem er von einem »neuen« <Bund> spricht, hat er den ersten für veraltet erklärt; was aber veraltet und sich überlebt*, ist dem Verschwinden nahe*.", footnotes: ["o. altersschwach wird; o. greisenhaft wird", "℘ Röm 10,4"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Es hatte nun zwar auch der erste <Bund> Satzungen des Dienstes* und das irdische* Heiligtum.", heading: "Der alttestamentliche ist nur Abbild des vollkommenen Gottesdienstes", footnotes: ["o. Gottesdienstes\n℘ Röm 9,4", "o. weltliche"] },
      { number: 2, text: "Denn es wurde ein Zelt aufgerichtet*, das vordere* — in dem sowohl der Leuchter als auch der Tisch und die Schaubrote* waren —, das das Heilige genannt wird*,", footnotes: ["℘ 2Mo 39,32", "w. erste; so auch V. 6.8", "w. das Auslegen der Brote", "℘ 2Mo 40,22-24"] },
      { number: 3, text: "hinter dem zweiten Vorhang aber ein Zelt, das das Allerheiligste genannt wird*,", footnotes: ["℘ 2Mo 26,31-33"] },
      { number: 4, text: "das einen goldenen Räucheraltar* und die überall mit Gold überdeckte Lade des Bundes* hatte, in welcher der goldene Krug, der das Manna enthielt*, und der Stab Aarons, der gesprosst hatte*, und die Tafeln des Bundes* waren;", footnotes: ["℘ 3Mo 16,12.13; 1Kö 6,22", "℘ 2Mo 25,11", "℘ 2Mo 16,33", "℘ 4Mo 17,23.25", "℘ 2Mo 40,20; 5Mo 10,5; 1Kö 8,9"] },
      { number: 5, text: "oben über ihr aber die Cherubim der Herrlichkeit, die den Versöhnungsdeckel* überschatteten*, von welchen Dingen jetzt nicht im Einzelnen zu reden ist.", footnotes: ["o. Sühnedeckel; dasselbe Wort wie Röm 3,25", "℘ 2Mo 25,18-21"] },
      { number: 6, text: "Da aber dies so eingerichtet ist, gehen zwar in das vordere Zelt die Priester allezeit hinein und verrichten die Dienste*,", footnotes: ["o. die Gottesdienste\n℘ 2Mo 30,7.8; 4Mo 18,3.4; 1Chr 23,13"] },
      { number: 7, text: "in das zweite aber einmal im Jahr allein der Hohepriester, nicht ohne Blut, das er darbringt für sich selbst und für die Verirrungen des Volkes*.", footnotes: ["℘ V. 25; 2Mo 30,10; 3Mo 16"] },
      { number: 8, text: "Damit zeigt der Heilige Geist an*, dass der Weg zum Heiligtum noch nicht offenbart ist, solange das vordere Zelt noch Bestand hat.", footnotes: ["℘ Kap. 10,15"] },
      { number: 9, text: "Dieses ist ein Gleichnis für die gegenwärtige Zeit, nach dem sowohl Gaben als auch Schlachtopfer dargebracht werden, die im Gewissen den nicht vollkommen machen können, der den Gottesdienst ausübt*.", footnotes: ["o. der dient\n℘ Kap. 7,19; Gal 3,21"] },
      { number: 10, text: "Es sind nur — neben Speisen* und Getränken und verschiedenen Waschungen* — Satzungen des Fleisches*, die bis zur Zeit einer richtigen Ordnung* auferlegt sind*.", footnotes: ["℘ Kap. 13,9; 3Mo 11,2", "℘ 3Mo 15,18; 4Mo 19,8; Kol 2,16", "℘ Kap. 7,16", "o. einer Berichtigung", "℘ Gal 4,2"] },
      { number: 11, text: "Christus aber ist gekommen als Hoherpriester der zukünftigen* Güter und ist durch das größere und vollkommenere Zelt — das nicht mit Händen gemacht*, das heißt, nicht von dieser Schöpfung ist —", heading: "Das einmalige und vollkommene Opfer Jesu", footnotes: ["mit anderen Handschr.: gewordenen", "℘ Kap. 8,2"] },
      { number: 12, text: "und nicht mit Blut von Böcken und Kälbern*, sondern mit seinem eigenen Blut* ein für alle Mal* in das Heiligtum hineingegangen und hat <uns> eine ewige Erlösung erworben*.", footnotes: ["℘ Kap. 10,4; 3Mo 16,15", "℘ Apg 20,28; Kol 1,20", "℘ Kap. 7,27", "o. hineingegangen, als er <für uns> eine ewige Erlösung gefunden hatte\n℘ Eph 1,7"] },
      { number: 13, text: "Denn wenn das Blut von Böcken und Stieren* und die Asche einer jungen Kuh, auf die Unreinen gesprengt, zur Reinheit des Fleisches heiligt*,", footnotes: ["℘ Kap. 10,4; 3Mo 16,15", "℘ 4Mo 19,9"] },
      { number: 14, text: "wie viel mehr wird das Blut des Christus, der sich selbst* durch den ewigen Geist <als Opfer> ohne Fehler* Gott dargebracht hat, euer* Gewissen reinigen* von toten Werken*, damit ihr dem lebendigen Gott dient*!", footnotes: ["℘ Kap. 1,3; Joh 10,18; Eph 5,2", "℘ 1Petr 1,19", "mit anderen alten Handschr.: unser", "℘ 1Jo 1,7", "℘ Kap. 6,1; 10,22", "o. Gottesdienst darbringt\n℘ 1Thes 1,9"] },
      { number: 15, text: "Und darum ist er Mittler eines neuen Bundes*, damit, da der Tod geschehen ist zur Erlösung von den Übertretungen unter dem ersten Bund*, die Berufenen die Verheißung des ewigen Erbes empfangen*.", footnotes: ["℘ Kap. 8,6", "℘ Apg 13,39", "℘ Apg 20,32"] },
      { number: 16, text: "— Denn wo ein Testament* ist, da muss notwendig der Tod dessen eintreten, der das Testament gemacht hat.", footnotes: ["griech. dasselbe Wort wie »Bund«"] },
      { number: 17, text: "Denn ein Testament ist gültig, wenn der Tod eingetreten ist*, weil es niemals Kraft hat, solange der lebt, der das Testament gemacht hat. —", footnotes: ["w. bei Toten"] },
      { number: 18, text: "Daher ist auch der erste <Bund> nicht ohne Blut eingeweiht worden." },
      { number: 19, text: "Denn als jedes Gebot nach dem Gesetz von Mose dem ganzen Volk mitgeteilt war, nahm er das Blut der Kälber und Böcke mit Wasser* und Purpurwolle und Ysop* und besprengte sowohl das Buch selbst als auch das ganze Volk", footnotes: ["℘ 1Jo 5,6", "ein kleiner Busch mit stark riechenden Blättern; er wurde u. a. beim Reinigungsopfer zum Besprengen verwendet"] },
      { number: 20, text: "und sprach: »Dies ist das Blut des Bundes, den Gott für euch geboten hat.«*", footnotes: ["℘ 2Mo 24,8"] },
      { number: 21, text: "Aber auch das Zelt und alle Gefäße des Dienstes besprengte er ebenso mit dem Blut*;", footnotes: ["℘ 2Mo 29,12; 3Mo 8,15.19"] },
      { number: 22, text: "und fast alle Dinge werden mit Blut gereinigt nach dem Gesetz*, und ohne Blutvergießen gibt es keine Vergebung*.", footnotes: ["℘ 3Mo 16,14-19", "℘ 3Mo 17,11; Mt 26,28"] },
      { number: 23, text: "<Es ist> nun nötig, dass die Abbilder der himmlischen Dinge* hierdurch gereinigt werden, die himmlischen Dinge selbst aber durch bessere Schlachtopfer als diese.", footnotes: ["℘ Kap. 8,5"] },
      { number: 24, text: "Denn Christus ist nicht hineingegangen in ein mit Händen gemachtes Heiligtum, ein Abbild des wahren <Heiligtums>, sondern in den Himmel selbst*, um jetzt vor dem Angesicht Gottes für uns zu erscheinen*,", footnotes: ["℘ Kap. 8,1", "℘ Kap. 7,25"] },
      { number: 25, text: "auch nicht, um sich selbst oftmals zu opfern, wie der Hohepriester alljährlich mit fremdem Blut in das Heiligtum hineingeht*", footnotes: ["℘ V. 7"] },
      { number: 26, text: "— sonst hätte er oftmals leiden müssen von Grundlegung der Welt an —; jetzt aber ist er einmal in der Vollendung der Zeitalter* offenbar geworden, um durch sein Opfer* die Sünde aufzuheben*.", footnotes: ["griech. Äonen\n℘ 1Kor 10,11; Gal 4,4", "o. Schlachtopfer", "℘ Kap. 1,3; 7,27; Dan 9,24; Joh 1,29; Röm 6,10"] },
      { number: 27, text: "Und wie es den Menschen bestimmt* ist, einmal zu sterben*, danach aber das Gericht*,", footnotes: ["w. gesetzt", "℘ 1Mo 3,19; 1Chr 29,15", "℘ Kap. 6,2"] },
      { number: 28, text: "so wird auch der Christus, nachdem er einmal geopfert worden ist, um vieler Sünden zu tragen*, zum zweiten Male ohne <Beziehung zur> Sünde* denen zum Heil* erscheinen*, die ihn erwarten*.", footnotes: ["℘ Jes 53,12; Röm 4,25; 1Petr 2,24", "d. h. sein Kommen hat nichts mehr mit der Sünde zu tun", "o. zur Rettung", "℘ Joh 14,3; 2Tim 4,8", "℘ 1Thes 1,10"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Denn da das Gesetz einen Schatten der zukünftigen Güter, nicht der Dinge Ebenbild selbst hat*, so kann es niemals mit denselben Schlachtopfern, die sie alljährlich darbringen, die Hinzunahenden für immer vollkommen machen*.", footnotes: ["℘ Kap. 8,5", "℘ Kap. 7,18.19"] },
      { number: 2, text: "Denn würde sonst nicht ihre Darbringung aufgehört haben, weil die den Gottesdienst Übenden*, einmal gereinigt, kein Sündenbewusstsein mehr gehabt hätten?", footnotes: ["w. weil die Dienenden"] },
      { number: 3, text: "Doch in jenen <Opfern> ist alljährlich ein Erinnern an die Sünden*;", footnotes: ["℘ 3Mo 16,34"] },
      { number: 4, text: "denn unmöglich kann Blut von Stieren und Böcken Sünden wegnehmen*.", footnotes: ["℘ Kap. 9,9; Mi 6,6.7"] },
      { number: 5, text: "Darum spricht er, als er in die Welt kommt: »Schlachtopfer und Opfergabe hast du nicht gewollt, einen Leib aber hast du mir bereitet*;", footnotes: ["℘ Kap. 2,14"] },
      { number: 6, text: "an Brandopfern und Sündopfern hast du kein Wohlgefallen gefunden*.", footnotes: ["℘ Ps 51,18"] },
      { number: 7, text: "Da sprach ich: Siehe, ich komme — in der Buchrolle steht von mir geschrieben* —, um deinen Willen, Gott, zu tun.«*", footnotes: ["℘ Joh 5,39", "℘ Ps 40,7-9; Joh 4,34"] },
      { number: 8, text: "Vorher sagt er: »Schlachtopfer und Opfergaben und Brandopfer und Sündopfer hast du nicht gewollt, auch kein Wohlgefallen daran gefunden«* — die doch nach dem Gesetz dargebracht werden —;", footnotes: ["℘ Ps 40,7-9; Joh 4,34"] },
      { number: 9, text: "dann sprach er: »Siehe, ich komme, um deinen Willen zu tun«* — er nimmt das Erste weg, um das Zweite aufzurichten*.", footnotes: ["℘ Kap. 7,18.19", "℘ Kap. 7,18.19"] },
      { number: 10, text: "In diesem Willen* sind wir geheiligt* durch das ein für alle Mal* geschehene Opfer des Leibes Jesu Christi*.", footnotes: ["d. h. aufgrund dieses Willens", "℘ Joh 17,19; Gal 1,4", "℘ Kap. 7,27", "℘ Eph 5,2"] },
      { number: 11, text: "Und jeder Priester steht täglich da*, verrichtet den Dienst und bringt oft dieselben Schlachtopfer dar, die niemals Sünden hinwegnehmen können*.", footnotes: ["℘ 2Mo 29,38", "℘ Kap. 9,9; Mi 6,6.7"] },
      { number: 12, text: "Dieser aber hat ein Schlachtopfer für Sünden dargebracht* und sich für immer gesetzt zur Rechten Gottes*.", footnotes: ["℘ Kap. 9,12.26", "℘ Kap. 1,3; Apg 7,56"] },
      { number: 13, text: "Fortan wartet er, bis seine Feinde hingelegt sind als Schemel seiner Füße*.", footnotes: ["℘ Kap. 1,13"] },
      { number: 14, text: "Denn mit einem Opfer hat er die, die geheiligt werden, für immer vollkommen gemacht*.", footnotes: ["℘ Kap. 2,11"] },
      { number: 15, text: "<Das> bezeugt uns aber auch der Heilige Geist*; denn nachdem er gesagt hat:", footnotes: ["℘ Kap. 9,8; Mk 12,36"] },
      { number: 16, text: "»Dies ist der Bund, den ich für sie errichten* werde nach jenen Tagen, spricht der Herr, ich werde meine Gesetze in* ihre Herzen geben und sie auch in* ihren Sinn* schreiben«*;", footnotes: ["o. mit ihnen schließen; o. für sie anordnen", "w. auf", "w. auf", "o. ihre Gesinnung; o. ihr Denken", "℘ Kap. 8,10; Jer 31,33.34"] },
      { number: 17, text: "und: »Ihrer Sünden und ihrer Gesetzlosigkeiten werde ich nicht mehr gedenken*.«", footnotes: ["℘ Kap. 8,12; Ps 103,12"] },
      { number: 18, text: "Wo aber Vergebung dieser <Sünden> ist, gibt es kein Opfer für Sünde mehr." },
      { number: 19, text: "Da wir nun, Brüder, durch das Blut Jesu Freimütigkeit haben zum Eintritt in das Heiligtum*,", heading: "Mahnung zu Glaubenszuversicht und Treue — Warnung vor Rückfall", footnotes: ["℘ Kap. 7,25; Eph 2,18"] },
      { number: 20, text: "den er uns eröffnet* hat als einen neuen und lebendigen Weg* durch den Vorhang — das ist durch sein Fleisch* —,", footnotes: ["o. eingeweiht; im Griech. dasselbe Wort wie in Kap. 9,18", "℘ Joh 14,6", "℘ Mt 27,51; Joh 1,14"] },
      { number: 21, text: "und einen großen Priester über das Haus Gottes*,", footnotes: ["℘ Kap. 3,1.6; Sach 6,13"] },
      { number: 22, text: "so lasst uns hinzutreten mit wahrhaftigem Herzen* in voller Gewissheit* des Glaubens*, die Herzen besprengt <und damit gereinigt> vom bösen Gewissen* und den Leib gewaschen mit reinem Wasser*.", footnotes: ["℘ Joh 4,24", "o. in <der> Fülle", "℘ Kap. 11,1", "℘ Kap. 9,14", "℘ 2Mo 29,4; 2Kor 7,1"] },
      { number: 23, text: "Lasst uns das Bekenntnis der Hoffnung unwandelbar festhalten* — denn treu ist er, der die Verheißung gegeben hat* —,", footnotes: ["℘ Kap. 3,6; 4,14", "℘ Kap. 6,18; 1Kor 1,9"] },
      { number: 24, text: "und lasst uns aufeinander achthaben, um uns zur Liebe* und zu guten Werken* anzureizen,", footnotes: ["℘ 1Jo 4,7", "℘ Tit 2,14"] },
      { number: 25, text: "indem wir unser Zusammenkommen nicht versäumen*, wie es bei einigen Sitte ist, sondern <einander> ermuntern*, und <das> umso mehr, je mehr ihr den Tag herannahen seht*!", footnotes: ["o. im Stich lassen", "℘ Kap. 3,13", "℘ V. 37"] },
      { number: 26, text: "Denn wenn wir mutwillig sündigen, nachdem wir die Erkenntnis der Wahrheit empfangen haben*, bleibt kein Schlachtopfer für Sünden mehr übrig,", footnotes: ["℘ Kap. 6,4"] },
      { number: 27, text: "sondern ein furchtbares Erwarten des Gerichts und der Eifer eines Feuers, das die Widersacher verzehren wird*.", footnotes: ["w. das im Begriff steht . . . zu verzehren\n℘ Jes 26,11; 2Thes 1,8"] },
      { number: 28, text: "Hat jemand das Gesetz Moses verworfen*, stirbt er ohne Barmherzigkeit* auf zwei oder drei Zeugen hin*.", footnotes: ["o. gebrochen", "℘ Kap. 2,2", "℘ Mt 18,16"] },
      { number: 29, text: "Wie viel schlimmere Strafe, meint ihr, wird der verdienen, der den Sohn Gottes mit Füßen getreten und das Blut des Bundes*, durch das er geheiligt wurde, für gemein* erachtet und den Geist der Gnade geschmäht hat*?", footnotes: ["℘ Kap. 13,20; Mt 26,28", "o. gewöhnlich; o. profan; o. <kultisch> unrein", "℘ Kap. 2,3; Mt 12,31.32"] },
      { number: 30, text: "Denn wir kennen den, der gesagt hat: »Mein ist die Rache, ich will vergelten«; und wiederum: »Der Herr wird sein Volk richten.«*", footnotes: ["℘ 5Mo 32,35.36; Ps 135,14; Röm 12,19"] },
      { number: 31, text: "Es ist furchtbar, in die Hände des lebendigen Gottes zu fallen*!", footnotes: ["℘ 5Mo 32,41"] },
      { number: 32, text: "Gedenkt aber der früheren Tage, in denen ihr, nachdem ihr erleuchtet worden wart, viel Leidenskampf erduldet habt*,", footnotes: ["℘ Phil 1,29.30"] },
      { number: 33, text: "als ihr teils durch Schmähungen und Bedrängnisse zur Schau gestellt und teils Gefährten derer wurdet, denen es so erging*!", footnotes: ["℘ 1Kor 4,9; 1Thes 2,14"] },
      { number: 34, text: "Denn ihr habt sowohl mit den Gefangenen gelitten* als auch den Raub eurer Güter mit Freuden aufgenommen*, da ihr wisst, dass ihr für euch selbst einen besseren und bleibenden Besitz habt*.", footnotes: ["℘ Kap. 6,10; 13,3; 2Tim 1,16", "℘ Jak 1,2; 1Petr 4,13", "℘ Mt 6,20; 19,29"] },
      { number: 35, text: "Werft nun eure Zuversicht* nicht weg, die eine große Belohnung hat*.", footnotes: ["o. Freimütigkeit; o. Unerschrockenheit", "℘ Kap. 11,26"] },
      { number: 36, text: "Denn Ausharren habt ihr nötig*, damit ihr, nachdem ihr den Willen Gottes getan habt, die Verheißung davontragt*.", footnotes: ["℘ Mk 13,13; Lk 8,15; 21,19; Jak 5,7", "℘ Kap. 6,12.15"] },
      { number: 37, text: "Denn noch eine ganz kleine Weile, <und> der Kommende wird kommen* und nicht säumen*.", footnotes: ["℘ 1Thes 4,16", "℘ V. 25; Hab 2,3; Phil 4,5; Jak 5,8; 2Petr 3,9; Offb 3,11"] },
      { number: 38, text: "»Mein Gerechter aber wird aus Glauben leben«*; und: »Wenn er sich zurückzieht, wird meine Seele kein Wohlgefallen an ihm haben*.«", footnotes: ["℘ Hab 2,3.4; Röm 1,17; Gal 3,11", "℘ Jer 14,10; Lk 9,62; 1Kor 10,5"] },
      { number: 39, text: "Wir aber sind nicht von denen, die zurückweichen zum Verderben, sondern von denen, die glauben zur* Gewinnung des Lebens*.", footnotes: ["w. Wir aber sind nicht vom Zurückweichen zum Verderben, sondern vom Glauben zur", "o. der Seele\n℘ 1Petr 1,9"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Der Glaube aber ist eine Wirklichkeit* dessen, was man hofft*, ein Überführtsein von Dingen, die man nicht sieht*.", heading: "Der Glaube: sein Wesen und seine Wirkungen — Glaubenszeugen des Alten Bundes", footnotes: ["o. Grundlage", "℘ Röm 8,25", "℘ Kap. 10,22; 2Kor 4,18; 5,7"] },
      { number: 2, text: "Denn durch ihn haben die Alten Zeugnis erlangt*.", footnotes: ["℘ V. 39"] },
      { number: 3, text: "Durch Glauben verstehen wir, dass die Welten* durch Gottes Wort bereitet worden sind*, so dass das Sichtbare nicht aus Erscheinendem* geworden ist*.", footnotes: ["o. die Zeitalter; o. die Ewigkeiten; griech. Äonen", "℘ 1Mo 1,1; Ps 33,6", "d. h. aus Dingen, die mit den Sinnen wahrgenommen werden können", "℘ Ps 33,9"] },
      { number: 4, text: "Durch Glauben brachte Abel Gott ein besseres Opfer dar als Kain*, durch welchen <Glauben> er das Zeugnis erhielt, gerecht zu sein*, indem Gott Zeugnis gab zu seinen Gaben; und durch diesen <Glauben> redet er noch, obgleich er gestorben ist*.", footnotes: ["℘ 1Mo 4,4.5", "℘ Mt 23,35", "℘ Kap. 12,24"] },
      { number: 5, text: "Durch Glauben wurde Henoch entrückt, so dass er den Tod nicht sah, und er wurde nicht gefunden, weil Gott ihn entrückt hatte; denn vor der Entrückung hat er das Zeugnis gehabt, dass er Gott wohlgefallen habe*. —", footnotes: ["℘ 1Mo 5,24"] },
      { number: 6, text: "Ohne Glauben aber ist es unmöglich, <ihm> wohlzugefallen; denn wer Gott naht, muss glauben, dass er ist* und denen, die ihn suchen, ein Belohner sein wird*.", footnotes: ["℘ Ps 10,4", "℘ 2Chr 15,7"] },
      { number: 7, text: "Durch Glauben baute Noah, als er eine göttliche Weisung über das, was noch nicht zu sehen war, empfangen hatte, von Furcht bewegt*, eine Arche* zur Rettung seines Hauses*. Durch ihn* verurteilte er die Welt* und wurde Erbe der Gerechtigkeit, die nach dem Glauben ist*.", footnotes: ["Andere üs.: voller Gottesfurcht", "℘ 1Mo 6,22", "℘ 1Mo 7,7", "d. h. durch den Glauben", "℘ 1Petr 3,20", "℘ 1Mo 15,6; Röm 3,22"] },
      { number: 8, text: "Durch Glauben war Abraham, als er gerufen wurde, gehorsam, auszuziehen an den Ort, den er zum Erbteil empfangen sollte*; und er zog aus, ohne zu wissen, wohin er komme*.", footnotes: ["℘ Apg 7,3.4", "℘ 1Mo 12,1-4"] },
      { number: 9, text: "Durch Glauben siedelte er sich im Land der Verheißung an wie in einem fremden* und wohnte in Zelten mit Isaak und Jakob*, den Miterben derselben Verheißung*;", footnotes: ["℘ 1Mo 17,8; 23,4", "℘ 1Mo 13,18; 26,25; 35,21", "℘ Kap. 6,17; 1Mo 26,3; 35,12"] },
      { number: 10, text: "denn er erwartete die Stadt, die Grundlagen hat*, deren Baumeister und Schöpfer* Gott ist*.", footnotes: ["℘ Kap. 12,22; 13,14; Offb 21,14", "o. Bildner", "℘ V. 16; 2Kor 5,1"] },
      { number: 11, text: "Durch Glauben empfing er auch mit Sara, obwohl sie unfruchtbar war, Kraft, Nachkommenschaft* zu zeugen*, und zwar über die geeignete Zeit des Alters hinaus*, weil er den für treu erachtete, der die Verheißung gegeben hatte.", footnotes: ["w. Samen", "Der griech. Text kann auch übersetzt werden: Durch Glauben empfing selbst Sara, obwohl unfruchtbar, Kraft zur Gründung (o. Zeugung) einer Nachkommenschaft (w. eines Samens).\n℘ 1Mo 21,2", "℘ 1Mo 17,17; 18,12; Röm 4,19"] },
      { number: 12, text: "Deshalb sind auch von einem, und zwar Gestorbenen, <so viele> geboren worden wie die Sterne des Himmels an Menge und wie der Sand am Ufer des Meeres, der unzählbar ist*.", footnotes: ["℘ 1Mo 22,17; 5Mo 1,10; 1Kö 4,20"] },
      { number: 13, text: "Diese alle sind im Glauben* gestorben und haben die Verheißungen nicht erlangt, sondern sahen sie von fern und begrüßten sie* und bekannten, dass sie Fremde und ohne Bürgerrecht* auf der Erde seien*.", footnotes: ["o. dem Glauben gemäß", "℘ Joh 8,56", "w. Fremdlinge; d. h. Menschen, die vorübergehend in einem fremden Land leben", "℘ 1Mo 23,4; 47,9; Ps 39,13; 1Petr 2,11"] },
      { number: 14, text: "Denn die, die solches sagen, zeigen deutlich, dass sie ein Vaterland suchen*.", footnotes: ["o. ersehnen; o. erstreben"] },
      { number: 15, text: "Und wenn sie an jenes gedacht hätten, von dem sie ausgezogen waren, so hätten sie Zeit gehabt zurückzukehren." },
      { number: 16, text: "Jetzt aber trachten sie nach einem besseren, das ist nach einem himmlischen*. Darum schämt sich Gott ihrer nicht, ihr Gott genannt zu werden*, denn er hat ihnen eine Stadt bereitet*.", footnotes: ["℘ Phil 3,20", "℘ 2Mo 3,6.15; Mt 22,32", "℘ V. 10"] },
      { number: 17, text: "Durch Glauben hat Abraham, als er geprüft* wurde, den Isaak dargebracht*, und er, der die Verheißungen empfangen hatte, brachte den einzigen* <Sohn> dar,", footnotes: ["o. versucht; o. auf die Probe gestellt", "℘ 1Mo 22,10; Jak 2,21", "griech. monogenes; s. Anm. zu Joh 1,14"] },
      { number: 18, text: "über den gesagt worden war: »In Isaak soll deine Nachkommenschaft genannt werden«*,", footnotes: ["℘ 1Mo 21,12; Röm 9,7"] },
      { number: 19, text: "indem er dachte*, dass Gott auch aus den Toten erwecken könne, von woher er ihn auch im Gleichnis empfing*.", footnotes: ["o. damit rechnete", "℘ Röm 4,17"] },
      { number: 20, text: "Durch Glauben segnete Isaak auch im Hinblick auf zukünftige Dinge den Jakob und den Esau*.", footnotes: ["℘ 1Mo 27,27-29.39.40"] },
      { number: 21, text: "Durch Glauben segnete Jakob sterbend einen jeden der Söhne Josefs* und betete an* über der Spitze seines Stabes*.", footnotes: ["℘ 1Mo 48,20", "d. h. neigte sich", "℘ 1Mo 47,31"] },
      { number: 22, text: "Durch Glauben gedachte Josef sterbend* des Auszugs der Söhne Israels und traf Anordnung wegen seiner Gebeine*.", footnotes: ["w. <sein Leben> beschließend", "℘ 1Mo 50,25; 2Mo 13,19; Jos 24,32"] },
      { number: 23, text: "Durch Glauben wurde Mose nach seiner Geburt drei Monate von seinen Eltern verborgen, weil sie sahen, dass das Kind schön war*; und sie fürchteten das Gebot des Königs nicht*.", footnotes: ["℘ 2Mo 2,2; Apg 7,20", "℘ 2Mo 1,22"] },
      { number: 24, text: "Durch Glauben weigerte sich Mose, als er groß geworden war, ein Sohn der Tochter Pharaos zu heißen*,", footnotes: ["℘ 2Mo 2,11"] },
      { number: 25, text: "und zog es vor, <lieber> zusammen mit dem Volk Gottes geplagt zu werden, als den zeitlichen Genuss der Sünde zu haben," },
      { number: 26, text: "indem er die Schmach des Christus* für größeren Reichtum hielt als die Schätze Ägyptens; denn er schaute auf die Belohnung*.", footnotes: ["℘ Kap. 13,13; Ps 69,11", "℘ Kap. 10,35; Mt 5,12"] },
      { number: 27, text: "Durch Glauben verließ er Ägypten* und fürchtete die Wut des Königs nicht*; denn er hielt standhaft aus, als sähe er den Unsichtbaren.", footnotes: ["℘ 2Mo 12,51", "℘ 2Mo 10,28.29"] },
      { number: 28, text: "Durch Glauben hat er das Passah gefeiert und die Bestreichung mit Blut ausgeführt, damit der Verderber der Erstgeburt sie nicht antastete*.", footnotes: ["℘ 2Mo 12,12.13"] },
      { number: 29, text: "Durch Glauben gingen sie durch das Rote Meer wie über trockenes Land, während die Ägypter, als sie es versuchten, verschlungen wurden*.", footnotes: ["℘ 2Mo 14,21-28"] },
      { number: 30, text: "Durch Glauben fielen die Mauern Jerichos, nachdem sie sieben Tage umzogen worden waren*.", footnotes: ["℘ Jos 6,20"] },
      { number: 31, text: "Durch Glauben kam Rahab, die Hure, nicht mit den Ungehorsamen um, da sie die Kundschafter in Frieden aufgenommen hatte*.", footnotes: ["℘ Jos 6,25; Jak 2,25"] },
      { number: 32, text: "Und was soll ich noch sagen? Denn die Zeit würde mir fehlen, wenn ich erzählen wollte von Gideon*, Barak*, Simson*, Jeftah*, David* und Samuel* und den Propheten*,", footnotes: ["℘ Ri 6,11", "℘ Ri 4,6", "℘ Ri 13,24", "℘ Ri 11,1", "℘ 1Sam 16,13", "℘ 1Sam 1,20", "℘ Jak 5,10"] },
      { number: 33, text: "die durch Glauben Königreiche bezwangen*, Gerechtigkeit wirkten*, Verheißungen* erlangten*, der Löwen Rachen verstopften*,", footnotes: ["℘ 2Sam 8,1-6", "℘ 2Sam 8,15", "d. h. das, was ihnen verheißen war", "℘ Kap. 6,12", "℘ Ri 14,6; Dan 6,23"] },
      { number: 34, text: "des Feuers Kraft auslöschten*, des Schwertes Schärfe entgingen, aus der Schwachheit Kraft gewannen, im Kampf stark wurden, der Fremden Heere zurücktrieben.", footnotes: ["℘ Dan 3,25"] },
      { number: 35, text: "Frauen erhielten ihre Toten durch Auferstehung wieder*; andere aber wurden gefoltert, da sie die Befreiung nicht annahmen, um eine bessere Auferstehung zu erlangen*.", footnotes: ["℘ Lk 7,15; 2Kö 4,35; 1Kö 17,22", "℘ Mt 16,25"] },
      { number: 36, text: "Andere aber wurden durch Verhöhnung* und Geißelung* versucht, dazu durch Fesseln und Gefängnis*.", footnotes: ["steht im Griech. in der Mehrzahl\n℘ Ps 123,4; Jer 20,7.8", "steht im Griech. in der Mehrzahl", "℘ Jer 37,15"] },
      { number: 37, text: "Sie wurden gesteinigt*, zersägt*, starben den Tod durch das Schwert*, gingen umher in Schafpelzen, in Ziegenfellen, Mangel leidend, bedrängt, geplagt.", footnotes: ["℘ 1Kö 21,13; 2Chr 24,21", "Einige Handschr. fügen hinzu: versucht", "℘ 1Kö 19,10"] },
      { number: 38, text: "Sie, deren die Welt nicht wert war, irrten umher in Wüsten und Gebirgen und Höhlen und den Klüften der Erde*.", footnotes: ["℘ 1Kö 18,13"] },
      { number: 39, text: "Und diese alle, die durch den Glauben ein Zeugnis* erhielten, haben die Verheißung nicht erlangt*,", footnotes: ["℘ V. 2", "℘ Mt 13,17"] },
      { number: 40, text: "da Gott für uns etwas Besseres vorgesehen hat, damit sie nicht ohne uns vollendet werden sollten*.", footnotes: ["℘ Kap. 12,23; Offb 6,11"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Deshalb lasst nun auch uns, da wir eine so große Wolke von Zeugen um uns* haben, jede Bürde* und die <uns so> leicht umstrickende Sünde ablegen* und mit Ausdauer* laufen den vor uns liegenden Wettlauf*,", heading: "Ausharren in Prüfungen nach dem Vorbild Jesu", footnotes: ["w. uns umgebend", "℘ 2Tim 2,4", "℘ Röm 13,12", "o. Ausharren", "℘ 1Kor 9,24"] },
      { number: 2, text: "indem wir hinschauen auf Jesus*, den Anfänger* und Vollender des Glaubens, der um der vor ihm liegenden Freude willen die Schande nicht achtete* und das Kreuz erduldete* und sich gesetzt hat zur Rechten des Thrones Gottes*.", footnotes: ["w. wegschauend <von allem anderen> auf Jesus hin\n℘ Ps 25,15; Mt 17,8", "o. Urheber, o. Führer; einer, der in einer Sache den ersten Schritt tut und anderen vorangeht", "℘ Ps 69,20", "℘ Phil 2,8; 1Petr 2,24", "℘ Kap. 1,3"] },
      { number: 3, text: "Denn betrachtet den, der so großen Widerspruch von den Sündern gegen sich erduldet hat*, damit ihr nicht ermüdet und in euren Seelen ermattet*!", footnotes: ["℘ Lk 2,34", "℘ 2Thes 3,5"] },
      { number: 4, text: "Ihr habt im Kampf gegen die Sünde noch nicht bis aufs Blut widerstanden" },
      { number: 5, text: "und habt die Ermahnung* vergessen, die zu euch als zu Söhnen spricht: »Mein Sohn, schätze nicht gering des Herrn Züchtigung*, und ermatte nicht, wenn du von ihm gestraft* wirst!", footnotes: ["o. Ermunterung", "℘ Hi 5,17", "o. zurechtgewiesen"] },
      { number: 6, text: "Denn wen der Herr liebt, den züchtigt er*; er schlägt* aber jeden Sohn, den er aufnimmt.«*", footnotes: ["℘ 5Mo 8,5; Offb 3,19", "w. geißelt", "℘ Spr 3,11.12"] },
      { number: 7, text: "<Was> ihr erduldet, <ist> zur Züchtigung: Gott behandelt euch als Söhne. Denn ist der ein Sohn, den der Vater nicht züchtigt*?", footnotes: ["℘ Spr 13,24"] },
      { number: 8, text: "Wenn ihr aber ohne Züchtigung seid, deren alle teilhaftig geworden sind, so seid ihr Bastarde und nicht Söhne." },
      { number: 9, text: "Zudem hatten wir auch unsere leiblichen Väter* als Züchtiger und scheuten sie*. Sollen wir uns nicht vielmehr dem Vater der Geister* unterordnen* und leben?", footnotes: ["w. die Väter unseres Fleisches", "℘ 3Mo 19,3", "℘ 4Mo 16,22", "℘ Jak 4,7"] },
      { number: 10, text: "Denn sie züchtigten <uns> zwar für wenige Tage nach ihrem Gutdünken, er aber zum Nutzen*, damit wir seiner Heiligkeit teilhaftig werden.", footnotes: ["℘ 1Kor 11,32"] },
      { number: 11, text: "Alle Züchtigung scheint uns zwar für die Gegenwart nicht Freude, sondern Traurigkeit zu sein*; nachher aber gibt sie denen, die durch sie geübt sind, die friedvolle Frucht der Gerechtigkeit*.", footnotes: ["℘ 1Petr 1,6", "℘ Jes 32,17; Jak 3,18"] },
      { number: 12, text: "Darum »richtet auf die erschlafften Hände und die gelähmten Knie«*,", heading: "Heiligung im Blick auf das Ziel", footnotes: ["℘ Hi 4,3.4; Jes 35,3"] },
      { number: 13, text: "und »macht gerade Bahn für eure Füße!«*, damit das Lahme nicht abirre, sondern vielmehr geheilt werde.", footnotes: ["℘ Spr 4,26"] },
      { number: 14, text: "Jagt dem Frieden mit allen nach* und der Heiligung*, ohne die niemand den Herrn schauen wird*;", footnotes: ["℘ Ps 34,15; Röm 12,18; 1Petr 3,11", "℘ 2Kor 7,1; 1Petr 1,15.16", "℘ Mt 5,8"] },
      { number: 15, text: "und achtet darauf, dass nicht jemand an der Gnade Gottes Mangel leide*, dass nicht irgendeine Wurzel der Bitterkeit aufsprosse* und <euch> zur Last werde und durch sie viele verunreinigt werden;", footnotes: ["w. von der Gnade Gottes fernbleibt, o. zurückbleibt\n℘ 2Kor 6,1", "℘ 5Mo 29,17"] },
      { number: 16, text: "dass nicht jemand ein Hurer* oder ein Gottloser sei wie Esau, der für eine Speise sein Erstgeburtsrecht verkaufte*!", footnotes: ["℘ Eph 5,3", "℘ 1Mo 25,33"] },
      { number: 17, text: "Denn ihr wisst, dass er auch nachher, als er den Segen erben wollte, verworfen wurde, denn er fand keinen Raum zur Buße, obgleich er sie* mit Tränen eifrig suchte*.", footnotes: ["o. ihn; das griech. Fürwort kann sich sowohl auf »Segen« als auch auf »Buße« beziehen", "℘ 1Mo 27,34.38"] },
      { number: 18, text: "Denn ihr seid nicht gekommen zu etwas, das betastet werden konnte, und zu einem angezündeten Feuer* und dem Dunkel und der Finsternis* und dem Sturm", footnotes: ["o. und der von Feuer brannte. — Viele alte Handschr. fügen »Berg« hinzu; die Üs. lautet dann: Denn ihr seid nicht gekommen zu einem Berg, der betastet werden konnte, . . .", "℘ 5Mo 4,11"] },
      { number: 19, text: "und zu dem Schall der Posaune und der Stimme der Worte*, deren Hörer baten, dass das Wort nicht mehr an sie gerichtet werde*", footnotes: ["℘ 2Mo 19,16-19", "℘ 2Mo 20,19"] },
      { number: 20, text: "— denn sie konnten nicht ertragen, was angeordnet wurde: »Und wenn ein Tier den Berg berührt, soll es gesteinigt werden«*,", footnotes: ["℘ 2Mo 19,13"] },
      { number: 21, text: "und so furchtbar war die Erscheinung, dass Mose sagte: »Ich bin voll Furcht und Zittern«* —,", footnotes: ["℘ 5Mo 9,19"] },
      { number: 22, text: "sondern ihr seid gekommen zum Berg Zion und zur Stadt des lebendigen Gottes*, dem himmlischen Jerusalem*; und zu Myriaden* von Engeln*, einer Festversammlung;", footnotes: ["℘ Kap. 11,10; Ps 87,3.5; Eph 2,19", "℘ Gal 4,26; Offb 3,12", "d. i. Zehntausende oder auch unzählige Tausende", "℘ Dan 7,10; Offb 5,11"] },
      { number: 23, text: "und zu der Gemeinde* der Erstgeborenen, die in den Himmeln angeschrieben sind*; und zu Gott, dem Richter aller*; und zu den Geistern der vollendeten Gerechten*;", footnotes: ["o. Versammlung", "℘ Lk 10,20", "℘ 1Mo 18,25", "℘ Kap. 11,40"] },
      { number: 24, text: "und zu Jesus, dem Mittler eines neuen Bundes*; und zum Blut der Besprengung*, das besser redet als <das Blut> Abels*.", footnotes: ["℘ Kap. 8,6; Mk 14,24", "o. Reinigung\n℘ 1Petr 1,2", "℘ Kap. 11,4; 1Mo 4,10"] },
      { number: 25, text: "Seht zu, dass ihr den nicht abweist, der da redet! Denn wenn jene nicht entkamen, die den abwiesen, der auf Erden die göttlichen Weisungen gab; wie viel mehr wir <nicht>, wenn* wir uns von dem abwenden, der von den Himmeln her <redet>*!", footnotes: ["w. die", "℘ Kap. 2,3"] },
      { number: 26, text: "Dessen Stimme erschütterte damals die Erde*; jetzt aber hat er verheißen und gesagt: »Noch einmal werde ich nicht nur die Erde bewegen, sondern auch den Himmel.«*", footnotes: ["℘ 2Mo 19,18; Ps 68,9", "℘ Hag 2,6"] },
      { number: 27, text: "Aber das »noch einmal« deutet die Verwandlung der Dinge an, die als geschaffene erschüttert werden, damit die unerschütterlichen bleiben*.", footnotes: ["℘ Jes 51,6.8; Dan 2,44"] },
      { number: 28, text: "Deshalb lasst uns, da wir ein unerschütterliches Reich* empfangen*, dankbar sein, wodurch wir Gott wohlgefällig dienen mit Scheu und Furcht*!", footnotes: ["o. eine unerschütterliche Königsherrschaft", "℘ Lk 12,32", "℘ Ps 2,11; 1Petr 1,17"] },
      { number: 29, text: "Denn auch unser Gott »ist ein verzehrendes Feuer«*.", footnotes: ["℘ 5Mo 4,24; 9,3; Ps 18,9"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Die Bruderliebe bleibe*!", heading: "Mahnung zur Bruderliebe — Warnung vor Unzucht und Geldliebe", footnotes: ["℘ Joh 13,34; 1Petr 3,8"] },
      { number: 2, text: "Die Gastfreundschaft* vergesst nicht! Denn dadurch haben einige, ohne es zu wissen, Engel beherbergt*.", footnotes: ["℘ Röm 12,13", "℘ 1Mo 18,2-5; 19,2.3"] },
      { number: 3, text: "Gedenkt der Gefangenen* als Mitgefangene; derer, die geplagt werden, als <solche>, die auch selbst im Leib sind!", footnotes: ["℘ Kap. 10,34; Röm 12,15; Kol 4,18"] },
      { number: 4, text: "Die Ehe sei ehrbar in allem* und das Ehebett unbefleckt! Denn Unzüchtige* und Ehebrecher wird Gott richten*.", footnotes: ["o. bei allen", "o. Hurer", "℘ 2Petr 2,9.10"] },
      { number: 5, text: "Der Wandel sei ohne Geldliebe*; begnügt euch mit dem, was vorhanden ist*! Denn er hat gesagt: »Ich will dich nicht aufgeben und dich nicht verlassen«*,", footnotes: ["℘ Lk 12,15", "℘ 1Tim 6,6.8", "℘ 1Mo 28,15; 5Mo 31,6; Jos 1,5; 1Chr 28,20"] },
      { number: 6, text: "so dass wir zuversichtlich sagen können: »Der Herr ist mein Helfer, ich will mich nicht fürchten. Was soll mir ein Mensch tun?«*", footnotes: ["℘ Ps 118,6"] },
      { number: 7, text: "Gedenkt eurer Führer, die das Wort Gottes zu euch geredet haben*! Schaut den Ausgang ihres Wandels an, und ahmt ihren Glauben nach!", heading: "Mahnung zur Treue in der Nachfolge Jesu", footnotes: ["℘ 1Thes 3,6"] },
      { number: 8, text: "Jesus Christus <ist> derselbe gestern und heute und in Ewigkeit*.", footnotes: ["w. in die Zeitalter (griech. Äonen)\n℘ Kap. 7,24; Ps 102,28"] },
      { number: 9, text: "Lasst euch nicht fortreißen durch verschiedenartige und fremde Lehren*! Denn es ist gut, dass das Herz* durch Gnade gefestigt wird, nicht durch Speisen*, von denen die keinen Nutzen hatten, die danach wandelten*.", footnotes: ["℘ Eph 4,14", "℘ Jer 17,9", "℘ Kap. 9,10", "℘ 1Kor 8,8"] },
      { number: 10, text: "Wir haben einen Altar, von dem zu essen die kein Recht* haben, die dem Zelt dienen*.", footnotes: ["o. keine Vollmacht", "o. die <in> dem Zelt Gottesdienst darbringen"] },
      { number: 11, text: "Denn die Leiber der Tiere, deren Blut durch den Hohenpriester für die Sünde in das Heiligtum hineingetragen wird, werden außerhalb des Lagers verbrannt*.", footnotes: ["℘ 3Mo 4,12.21; 16,27"] },
      { number: 12, text: "Darum hat auch Jesus, um das Volk durch sein eigenes Blut zu heiligen, außerhalb des Tores gelitten*.", footnotes: ["℘ Mk 15,20"] },
      { number: 13, text: "Deshalb lasst uns zu ihm hinausgehen, außerhalb des Lagers*, und seine Schmach tragen*!", footnotes: ["℘ 2Mo 33,7", "℘ Kap. 11,26"] },
      { number: 14, text: "Denn wir haben hier keine bleibende Stadt, sondern die zukünftige suchen* wir*.", footnotes: ["o. ersehnen; o. erstreben", "℘ Kap. 11,10"] },
      { number: 15, text: "Durch ihn nun lasst uns Gott stets ein Opfer des Lobes darbringen*! Das ist: Frucht der Lippen, die seinen Namen bekennen*.", footnotes: ["℘ Ps 27,6; 50,14.23", "℘ Hos 14,3"] },
      { number: 16, text: "Das Wohltun und Mitteilen aber vergesst nicht*! Denn an solchen Opfern hat Gott Wohlgefallen*.", footnotes: ["℘ Kap. 6,12", "℘ Phil 4,18"] },
      { number: 17, text: "Gehorcht und fügt euch euren Führern*! Denn sie wachen über eure Seelen, als solche, die Rechenschaft geben werden*, damit sie dies mit Freuden tun und nicht mit Seufzen; denn dies wäre nicht nützlich für euch.", footnotes: ["℘ 1Thes 5,12.13; 1Petr 5,3", "℘ Hes 3,18.20"] },
      { number: 18, text: "Betet für uns*! Denn wir sind überzeugt, dass wir ein gutes Gewissen haben, da wir in allem einen guten Wandel zu führen begehren*.", heading: "Schlussermahnungen — Segenswünsche — Grüße", footnotes: ["℘ Kol 4,3", "℘ Apg 24,16"] },
      { number: 19, text: "Ich bitte <euch> aber umso mehr, dies zu tun, damit ich euch desto schneller wiedergegeben werde*.", footnotes: ["℘ Phim 22"] },
      { number: 20, text: "Der Gott des Friedens* aber, der den großen Hirten der Schafe* aus den Toten heraufgeführt hat* durch das Blut eines ewigen Bundes*, unseren Herrn Jesus,", footnotes: ["℘ Röm 15,33", "℘ Joh 10,11", "℘ 1Petr 1,21", "℘ Kap. 10,29; Hes 37,26; Sach 9,11"] },
      { number: 21, text: "vollende euch in allem Guten*, damit ihr seinen Willen tut*, indem er in uns schafft, was vor ihm wohlgefällig ist*, durch Jesus Christus, dem die Herrlichkeit sei von Ewigkeit zu Ewigkeit*! Amen*.", footnotes: ["℘ Kol 1,10; 2Thes 2,17", "℘ Kol 4,12", "℘ Phil 2,13; 2Thes 1,11", "w. in die Zeitalter der Zeitalter (griech. Äonen)", "Beteuerungsformel für die Wahrhaftigkeit des Gesagten; in den Evangelien am Anfang feierlicher Erklärungen Jesu mit »Wahrlich!« übersetzt; vgl. Offb 22,20\n℘ Röm 11,36"] },
      { number: 22, text: "Ich bitte euch aber, Brüder, ertragt das Wort der Ermahnung! Denn ich habe euch ja kurz geschrieben*.", footnotes: ["℘ 1Petr 5,12"] },
      { number: 23, text: "Wisst, dass unser Bruder Timotheus freigelassen ist, mit dem ich euch sehen werde, wenn er bald kommt." },
      { number: 24, text: "Grüßt alle eure Führer und alle Heiligen! Es grüßen euch die von Italien*. —", footnotes: ["℘ Phil 4,22"] },
      { number: 25, text: "Die Gnade sei mit euch allen*!", footnotes: ["℘ Kol 4,18"] },
    ]},
  ]
};
